import org.junit.jupiter.params.provider.*;

class SupportFundCommissionEvidenceTest {
    static final String INC="dab1e5ef-069b-4771-8eab-b0b0661aa1fb";
    static final LocalDateTime AT=LocalDateTime.of(2026,10,12,0,0,0);
    final ObjectMapper json=new ObjectMapper();
    final SupportFundJournalBindingService codec=new SupportFundJournalBindingService(mock(SupportFundJournalMapper.class),mock(DataSource.class),json);
    final SupportFundCommissionEvidence helper=new SupportFundCommissionEvidence(codec,json);
    static Map<String,Object> row(Object...v){var m=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
    static BigDecimal n(String s){return new BigDecimal(s).setScale(6);}
    Map<String,Object> wallet(long revision,String usd,String nex){return row("id",9L,"customerId",7L,"incarnation",INC,"revision",revision,"version",revision+20,"usdtAvailable",n(usd),"nexAvailable",n(nex),"cregisRiskHeld",n("0"),"pendingWithdraw",n("0"),"sandbox",0,"deleted",0,"createdAt",AT.minusDays(1),"userSandbox",0,"userDeleted",0);}
    Map<String,Object> raw(Map<String,Object> before,Map<String,Object> after){long revision=((Number)after.get("revision")).longValue();var r=row("id",revision,"incarnation",INC,"revision",revision,"observation","CHANGE","protocolSha256","d9126edf88cbca4d5c5d0814cb0207ca21d33c78ca00d52c755034fb9e3cbe2a","recordedDbUtc",AT.minusHours(8).plusSeconds(revision));for(var side:List.of("old","new")){var w=side.equals("old")?before:after;for(var pair:Map.of("id","Id","customerId","UserId","version","Version","usdtAvailable","UsdtAvailable","nexAvailable","NexAvailable","cregisRiskHeld","CregisRiskHeld","pendingWithdraw","PendingWithdraw","sandbox","Sandbox","deleted","IsDeleted","createdAt","CreatedAt").entrySet())r.put(side+pair.getValue(),w.get(pair.getKey()));}return r;}
    String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new AssertionError(e);}}
    final class Fixture {
        final String asset;final SupportCommissionReadMapper mapper=mock(SupportCommissionReadMapper.class);final SupportFundJournalMapper journal=mock(SupportFundJournalMapper.class);final DataSource ds=mock(DataSource.class);final SupportFundJournalBindingService binder=new SupportFundJournalBindingService(journal,ds,json);
        final List<Map<String,Object>> events=new ArrayList<>(),ledgers=new ArrayList<>(),raws=new ArrayList<>(),ops=new ArrayList<>(),parties=new ArrayList<>(),legs=new ArrayList<>();
        final Map<String,Integer> meta=new HashMap<>(Map.of("nx_wallet_ledger.created_at",0,"nx_commission_event.created_at",0,"nx_commission_event.updated_at",0));
        Fixture(String asset){this.asset=asset;events.add(row("id",88L,"customerId",7L,"commissionType","leadership","sourceUserId",8L,"sourceUserName",null,"layerNo",null,"orderNo","ORDER-1","orderAmountUsd",n("100"),"amountUsdt",asset.equals("USDT")?n("5"):n("0"),"amountNex",asset.equals("UVT")?n("5"):n("0"),"asset",asset,"status","UNLOCKED","version",1L,"unlockAt",AT,"frozenFromStatus",null,"remark","original","createdAt",AT.minusHours(1),"updatedAt",AT,"deleted",0,"userSandbox",0,"userDeleted",0));
            when(mapper.fundEvents(List.of(7L))).thenAnswer(i->events);when(mapper.fundLedgers(List.of(7L))).thenAnswer(i->ledgers);
            when(journal.insertOperation(anyMap())).thenAnswer(i->{var op=new LinkedHashMap<>(i.<Map<String,Object>>getArgument(0));op.put("id",(long)ops.size()+1);op.put("recordedDbUtc",AT.minusHours(8).plusSeconds(ops.size()+2));ops.add(op);return 1;});when(journal.operation(anyString())).thenAnswer(i->ops.stream().filter(o->i.getArgument(0).equals(o.get("operationKey"))).findFirst().orElse(null));
            when(journal.insertParty(anyLong(),eq(7L))).thenAnswer(i->{parties.add(row("operationId",i.getArgument(0),"customerId",7L));return 1;});when(journal.parties(anyLong())).thenAnswer(i->parties.stream().filter(p->i.getArgument(0).equals(p.get("operationId"))).toList());when(journal.insertLeg(anyLong(),eq(INC),anyLong())).thenAnswer(i->{legs.add(row("operationId",i.getArgument(0),"incarnation",INC,"revision",i.getArgument(2)));return 1;});when(journal.legs(anyLong())).thenAnswer(i->legs.stream().filter(l->i.getArgument(0).equals(l.get("operationId"))).toList());
        }
        void capture(String phase,Map<String,Object> before,Map<String,Object> after){
            var source=events.get(0);if(phase.equals("REVERSE")){source.put("status","REVERSED");source.put("version",2L);source.put("updatedAt",AT.plusSeconds(2));}
            long revision=((Number)after.get("revision")).longValue();String bucket=asset.equals("USDT")?"usdtAvailable":"nexAvailable";
            ledgers.add(row("id",(long)ledgers.size()+1,"customerId",7L,"bizNo",SupportCommissionFundAdapter.ledgerNo(88,phase),"bizType","TEAM_COMMISSION","asset",asset,"direction",phase.equals("RELEASE")?"IN":"OUT","amount",n("5"),"balanceAfter",after.get(bucket),"status","SUCCESS","remark","Commission wallet "+(phase.equals("RELEASE")?"release":"reversal")+" | eventId=88","createdAt",AT.plusSeconds(phase.equals("RELEASE")?0:2),"updatedAt",AT.plusSeconds(phase.equals("RELEASE")?0:2),"deleted",0));
            var raw=raw(before,after);raws.add(raw);when(mapper.fundWallets(7)).thenReturn(List.of(before),List.of(after));
            var lockedBefore=new HashMap<>(before);lockedBefore.put("userId",7L);lockedBefore.put("isDeleted",0);var lockedAfter=new HashMap<>(after);lockedAfter.put("userId",7L);lockedAfter.put("isDeleted",0);when(journal.lockWallet(7)).thenReturn(List.of(lockedBefore),List.of(lockedAfter));when(journal.journal(INC,revision-1,revision)).thenReturn(List.of(raw));
            var holder=new ConnectionHolder(mock(Connection.class));holder.setSynchronizedWithTransaction(true);TransactionSynchronizationManager.setActualTransactionActive(true);TransactionSynchronizationManager.initSynchronization();TransactionSynchronizationManager.bindResource(ds,holder);
            try{var adapter=new SupportCommissionFundAdapter(binder,mapper,new SupportCommissionReadService(mapper),json);var token=adapter.begin(7,88,phase);adapter.recorded(token);}finally{TransactionSynchronizationManager.unbindResource(ds);TransactionSynchronizationManager.clear();}
        }
        SupportFundCommissionEvidence.Inputs input(){return new SupportFundCommissionEvidence.Inputs(new SupportCommissionReadFacade.Sources(events,ledgers),raws,ops,parties,legs,meta);}
        Map<String,Object> op(String phase){return ops.stream().filter(o->phase.equals(o.get("phase"))).findFirst().orElseThrow();}
        SupportFundCommissionEvidence.Verified verify(String phase){var op=op(phase);var relevant=legs.stream().filter(l->op.get("id").equals(l.get("operationId"))).toList();return helper.verify(op,codec.read((String)op.get("sourceSnapshotJson")),codec.read((String)op.get("sourceProofJson")),binder.decodeReceipt(op,List.of(7L),relevant),input());}
        void coverage(Set<String> covered){helper.verifyCoverage(Set.of(7L),input(),covered);}
    }
    Fixture fixture(String asset,boolean reverse){var f=new Fixture(asset);var before=wallet(1,"10","20");var after=wallet(2,asset.equals("USDT")?"15":"10",asset.equals("UVT")?"25":"20");f.capture("RELEASE",before,after);if(reverse)f.capture("REVERSE",after,wallet(3,"10","20"));return f;}
    @ParameterizedTest @ValueSource(strings={"USDT","UVT"}) void realAdapterOwningReaderBinderAndHelperCloseBothCashPhases(String asset){var f=fixture(asset,true);for(String phase:List.of("RELEASE","REVERSE")){var v=f.verify(phase);assertThat(v.points()).hasSize(1);assertThat(v.coveredPhase()).isEqualTo("88:"+phase);assertThat(v.stamp().fractionalSecondDigits()).isZero();assertThat(f.op(phase).get("receiptSha256")).isNotNull();}f.coverage(Set.of("88:RELEASE","88:REVERSE"));assertThat(f.verify("RELEASE").stamp().succeededAt()).isEqualTo(AT);verify(f.journal,times(2)).insertOperation(anyMap());}
    @ParameterizedTest @ValueSource(strings={"USDT","UVT"}) void laterLegitimateStatusAndUpdatedAtDoNotEraseHistoricalRelease(String asset){var f=fixture(asset,false);f.events.get(0).put("status","REISSUED");f.events.get(0).put("version",7L);f.events.get(0).put("updatedAt",AT.plusDays(1));f.events.get(0).put("unlockAt",AT.plusDays(1));f.verify("RELEASE");f.coverage(Set.of("88:RELEASE"));}
    @ParameterizedTest @ValueSource(strings={"USDT","UVT"}) void consumedOriginalThenLaterActualCashUsesClawbackWithoutHistoryQualification(String asset){var f=fixture(asset,false);f.capture("REVERSE",wallet(7,"30","40"),wallet(8,asset.equals("USDT")?"25":"30",asset.equals("UVT")?"35":"40"));f.verify("REVERSE");f.coverage(Set.of("88:RELEASE","88:REVERSE"));assertThat(codec.read((String)f.op("REVERSE").get("orderedEventsJson")).get(0).path("action").asText()).isEqualTo("CLAWBACK");}
    @ParameterizedTest @ValueSource(strings={"USDT","UVT"}) void missingHistoricalReleaseCaptureDoesNotBlockActualReverseBindingButStatisticsStayUnproven(String asset){var f=fixture(asset,false);f.ops.clear();f.parties.clear();f.legs.clear();f.capture("REVERSE",wallet(7,"30","40"),wallet(8,asset.equals("USDT")?"25":"30",asset.equals("UVT")?"35":"40"));assertThat(f.op("REVERSE").get("receiptSha256")).isNotNull();assertThatThrownBy(()->f.verify("REVERSE")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->f.coverage(Set.of("88:RELEASE","88:REVERSE"))).isInstanceOf(IllegalArgumentException.class);}
    @ParameterizedTest @ValueSource(strings={"USDT","UVT"}) void positiveUnusedCurrencyFieldDoesNotInventASecondCashPayment(String asset){var f=new Fixture(asset);f.events.get(0).put(asset.equals("USDT")?"amountNex":"amountUsdt",n("3"));f.capture("RELEASE",wallet(1,"10","20"),wallet(2,asset.equals("USDT")?"15":"10",asset.equals("UVT")?"25":"20"));assertThat(f.verify("RELEASE").points()).hasSize(1);f.coverage(Set.of("88:RELEASE"));}
    static Stream<String> corruptions(){return Stream.of("missingEvent","duplicateEvent","missingReleaseLedger","missingReverseLedger","duplicateLedger","owner","asset","amount","userSandbox","userDeleted","eventDeleted","wrongSourceName","sourceCreatedAt","ledgerOwner","ledgerAmount","ledgerType","ledgerStatus","ledgerDirection","ledgerRemark","ledgerDeleted","ledgerBalance","missingRaw","duplicateRaw","wrongRawOwner","missingCash","wrongDelta","otherCurrencyDelta","heldDelta","revision","version","missingLeg","duplicateLeg","missingParty","duplicateParty","missingReleaseCapture","duplicateOperation","missingPrecision","precisionLoss","missingFlag","nonIntegralId","proofExtra","wrongReleaseRef");}
    @ParameterizedTest @MethodSource("corruptions") void inconsistentOriginalsOrCashNeverBecomeReady(String kind){var f=fixture("USDT",true);switch(kind){
        case "missingEvent"->f.events.clear();case "duplicateEvent"->f.events.add(new HashMap<>(f.events.get(0)));case "missingReleaseLedger"->f.ledgers.remove(0);case "missingReverseLedger"->f.ledgers.remove(1);case "duplicateLedger"->f.ledgers.add(new HashMap<>(f.ledgers.get(1)));case "owner"->f.events.get(0).put("customerId",8L);case "asset"->f.events.get(0).put("asset","UVT");case "amount"->f.events.get(0).put("amountUsdt",n("6"));case "userSandbox"->f.events.get(0).put("userSandbox",1);case "userDeleted"->f.events.get(0).put("userDeleted",1);case "eventDeleted"->f.events.get(0).put("deleted",1);case "wrongSourceName"->f.events.get(0).put("sourceUserName","changed");case "sourceCreatedAt"->f.events.get(0).put("createdAt",AT);case "ledgerOwner"->f.ledgers.get(1).put("customerId",8L);case "ledgerAmount"->f.ledgers.get(1).put("amount",n("6"));case "ledgerType"->f.ledgers.get(1).put("bizType","UNKNOWN");case "ledgerStatus"->f.ledgers.get(1).put("status","PENDING");case "ledgerDirection"->f.ledgers.get(1).put("direction","IN");case "ledgerRemark"->f.ledgers.get(1).put("remark","changed");case "ledgerDeleted"->f.ledgers.get(1).put("deleted",1);case "ledgerBalance"->f.ledgers.get(1).put("balanceAfter",n("99"));case "missingRaw"->f.raws.remove(1);case "duplicateRaw"->f.raws.add(new HashMap<>(f.raws.get(1)));case "wrongRawOwner"->f.raws.get(1).put("newUserId",8L);case "missingCash"->f.raws.get(1).remove("newUsdtAvailable");case "wrongDelta"->f.raws.get(1).put("newUsdtAvailable",n("9"));case "otherCurrencyDelta"->f.raws.get(1).put("newNexAvailable",n("19"));case "heldDelta"->f.raws.get(1).put("newCregisRiskHeld",n("1"));case "revision"->f.legs.get(1).put("revision",99L);case "version"->f.raws.get(1).put("newVersion",99L);case "missingLeg"->f.legs.remove(1);case "duplicateLeg"->f.legs.add(new HashMap<>(f.legs.get(1)));case "missingParty"->f.parties.remove(1);case "duplicateParty"->f.parties.add(new HashMap<>(f.parties.get(1)));case "missingReleaseCapture"->f.ops.remove(0);case "duplicateOperation"->f.ops.add(new HashMap<>(f.ops.get(1)));case "missingPrecision"->f.meta.clear();case "precisionLoss"->f.ledgers.get(1).put("createdAt",AT.plusNanos(1));case "missingFlag"->f.events.get(0).remove("userSandbox");case "nonIntegralId"->f.events.get(0).put("id",new BigDecimal("88.1"));case "proofExtra"->{var proof=(ObjectNode)codec.read((String)f.op("REVERSE").get("sourceProofJson"));proof.put("ready",true);f.op("REVERSE").put("sourceProofJson",encode(proof));}case "wrongReleaseRef"->{var events=(com.fasterxml.jackson.databind.node.ArrayNode)codec.read((String)f.op("REVERSE").get("orderedEventsJson"));((ObjectNode)events.get(0)).put("reference","COMMISSION:89:RELEASE");f.op("REVERSE").put("orderedEventsJson",encode(events));}default->throw new AssertionError(kind);}
        assertThatThrownBy(()->f.verify("REVERSE")).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->f.coverage(Set.of("88:RELEASE","88:REVERSE"))).isInstanceOf(RuntimeException.class);
    }
    @ParameterizedTest @ValueSource(strings={"missing","extra","malformedLedger","orphanLedger","orphanOperation"}) void exactReverseCoverageCannotSilentlyDropCash(String kind){var f=fixture("UVT",false);Set<String> covered=Set.of("88:RELEASE");switch(kind){case "missing"->covered=Set.of();case "extra"->covered=Set.of("88:RELEASE","88:REVERSE");case "malformedLedger"->f.ledgers.get(0).put("bizNo","F5-COMMISSION-088-RELEASE");case "orphanLedger"->{var l=new HashMap<>(f.ledgers.get(0));l.put("id",9L);l.put("bizNo","F5-COMMISSION-89-RELEASE");f.ledgers.add(l);}case "orphanOperation"->{var op=new HashMap<>(f.ops.get(0));op.put("id",99L);op.put("sourceKey","89");op.put("operationKey","COMMISSION:89:RELEASE");f.ops.add(op);f.parties.add(row("operationId",99L,"customerId",7L));}}var actual=covered;assertThatThrownBy(()->f.coverage(actual)).isInstanceOf(RuntimeException.class);}
    @Test void neverReleasedCoolingCancellationHasNoCashAndNoInventedDebit(){var f=new Fixture("USDT");f.events.get(0).put("status","REVERSED");f.coverage(Set.of());assertThat(f.ops).isEmpty();verifyNoInteractions(f.journal);}
    @ParameterizedTest @ValueSource(strings={"walletBoolean","userBoolean","walletNumeric","userNumeric"}) void trueSandboxSkipsOnlyProductionBindingExplicitly(String flag){var mapper=mock(SupportCommissionReadMapper.class);var journal=mock(SupportCommissionCaptureFacade.class);var fund=mock(ffdd.opsconsole.finance.facade.SupportFundJournalFacade.class);var w=wallet(1,"10","20");w.put(flag.startsWith("wallet")?"sandbox":"userSandbox",flag.endsWith("Boolean")?true:1);when(mapper.fundWallets(7)).thenReturn(List.of(w));var adapter=new SupportCommissionFundAdapter(fund,mapper,mock(SupportCommissionReadFacade.class),json);var token=adapter.begin(7,88,"RELEASE");adapter.recorded(token);verifyNoInteractions(fund);}
    @ParameterizedTest @ValueSource(strings={"missingWalletFlag","missingUserFlag","fractionFlag","stringFlag","missingWallet","duplicateWallet"}) void missingActualEnvironmentNeverDefaultsToProductionOrSandbox(String kind){var mapper=mock(SupportCommissionReadMapper.class);var fund=mock(ffdd.opsconsole.finance.facade.SupportFundJournalFacade.class);var w=wallet(1,"10","20");switch(kind){case "missingWalletFlag"->w.remove("sandbox");case "missingUserFlag"->w.remove("userSandbox");case "fractionFlag"->w.put("userSandbox",new BigDecimal(".1"));case "stringFlag"->w.put("sandbox","0");}when(mapper.fundWallets(7)).thenReturn(kind.equals("missingWallet")?List.of():kind.equals("duplicateWallet")?List.of(w,w):List.of(w));var adapter=new SupportCommissionFundAdapter(fund,mapper,mock(SupportCommissionReadFacade.class),json);assertThatThrownBy(()->adapter.begin(7,88,"RELEASE")).isInstanceOf(RuntimeException.class);verifyNoInteractions(fund);}
}
